Nothing like this exists in the repo yet, so here it is, standard library only. I haven't written it to a file; its self-check passed when run.

```python
import random
import time


def retry(fn, attempts=5, base=0.5, cap=30.0, exceptions=(Exception,), sleep=time.sleep):
    """Call fn(); on failure wait base * 2**n (capped, jittered) and try again."""
    for n in range(attempts):
        try:
            return fn()
        except exceptions:
            if n == attempts - 1:
                raise
            sleep(random.uniform(0, min(cap, base * 2 ** n)))


if __name__ == "__main__":
    calls, waits = [], []

    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise OSError("nope")
        return "ok"

    assert retry(flaky, sleep=waits.append) == "ok"
    assert len(calls) == 3 and len(waits) == 2 and waits[0] <= 0.5 and waits[1] <= 1.0
    try:
        retry(lambda: 1 / 0, attempts=2, sleep=waits.append)
    except ZeroDivisionError:
        pass
    else:
        raise AssertionError("should re-raise after last attempt")
    print("ok")
```

Usage: `retry(lambda: fetch(url), exceptions=(ConnectionError, TimeoutError))`. Narrow `exceptions` when you use it, since the default retries on everything, including real bugs.

